-- Organizations: the tenant every other row is scoped to (plan, Technical -> Data model).
-- Keys are UUID v7, generated by the server: PostgreSQL 16 has no uuidv7() function.
-- Migrations are forward-only (expand/contract), so there is no down migration.
CREATE TABLE organizations (
    id          uuid        PRIMARY KEY,
    slug        text        NOT NULL UNIQUE,
    name        text        NOT NULL,
    settings    jsonb       NOT NULL DEFAULT '{}'::jsonb,
    branding    jsonb       NOT NULL DEFAULT '{}'::jsonb,
    created_at  timestamptz NOT NULL DEFAULT now(),
    updated_at  timestamptz NOT NULL DEFAULT now()
);
